"""Compose the completed Gen3 findings from the prespecified outputs only."""
import json
from pathlib import Path
import numpy as np
from medical_uav.training.io import write_json


def read(p):return json.loads(Path(p).read_text())


def main():
    dev=read('results/gen3_development.json');test=read('results/gen3_test_v3.json');bench=read('results/gen3_inference.json');audit=read('results/gen3_training_audit.json');methods=['destination','urgency','coordinated']
    out=['# Gen3 — urgency preservation and PICK–DELIVER coordination','','Two separate hypotheses extend frozen Gen2 destination conditioning. No training-objective, reward, PPO, interface, candidate count or budget change is included. All prior results and model weights remain available. The user explicitly kept the original overall Dev selection rule, without subtype guardrails.','','## New Test-v3: same-day comparison','','| Method | Low (%) | Medium (%) | High (%) | Equal (%) |','|---|---:|---:|---:|---:|']
    for m in methods+['slack']:
        r=test['methods'][m];out.append('| '+m+' | '+' | '.join(f'{100*v:.2f} ± {100*r["sample_sd"][i]:.2f}' if r['sample_sd'] else f'{100*v:.2f}' for i,v in enumerate(r['mean']))+' |')
    out+=['','± is sample SD across five learners, not an optimality gap or confidence interval. Test-v3 uses100 new demand IDs400000–400099, fixed map0. IDs were sealed before development; all three methods and fifteen best-model hashes were sealed before opening the holdout. Absolute scores should not be subtracted from previous Test cohorts.','','| Primary contrast | Equal delta (pp) | Paired joint95% (pp) | Positive learner pairs |','|---|---:|---:|---:|']
    primary={}
    for m in methods[1:]:
        r=test['comparisons'][m+' - destination']['loads']['equal'];primary[m]=r;ci=r['joint_95_percentile'];out.append(f'| {m} − destination | {100*r["estimate"]:+.2f} | [{100*ci[0]:+.2f},{100*ci[1]:+.2f}] | {sum(x>0 for x in r["learner_mean_values"])}/5 |')
    out+=['','Paired crossed learner-ID/day-ID product bootstrap,10,000 repetitions. All subtype comparisons, eligible days, release counts and separate learner/day components are in [Test-v3 detail](gen3_test_v3.md). Intervals are exploratory pointwise95%, without familywise correction. Five learners and a single map limit claims.','','## Development and retention','','| Method | Dev best | Dev last | Dev last3 | Dev-extra best | Dev-extra last |','|---|---:|---:|---:|---:|---:|']
    retention={}
    for m in methods:
        tail=np.array([r['on_time'] for r in dev['curves'][m]])[:,-3:,3].mean()
        values=[dev['dev_best']['methods'][m]['mean'][3],dev['dev_last']['methods'][m]['mean'][3],float(tail),dev['dev_extra_best']['methods'][m]['mean'][3],dev['dev_extra_last']['methods'][m]['mean'][3]];retention[m]=values
        out.append('| '+m+' | '+' | '.join(f'{100*v:.2f}%' for v in values)+' |')
    out+=['','Tail uses819,200/921,600/1,024,000 transitions. Dev-extra is development. Only best models are evaluated on Test-v3, so last-model stability is not claimed on the holdout.','','## Initial type diagnosis and remaining failures','','Before training, frozen M5 and Gen2 destination policies were replayed over3,000 Dev-extra full days; every original day field and diagnostic remained exact. Sample changes at Medium/High were −0.69/−1.03 pp, with paired intervals[−2.36,+0.98]/[−3.19,+1.02] pp. These do not establish a persistent category sacrifice. No hard type tolerance was fitted to Test-v2 results.','', 'Failure classification retains never-visible orders, first-visible/pre-pick direct slack, expired-before/after-pick outcomes, action underway at deadline crossings and urgent-cargo order-state counts. These are observational classifications, not proven avoidable errors. See [initial diagnosis](gen3_initial_diagnostics.md) and complete `failure_patterns` in the development/Test JSON. All four types and all loads are shown; no favorable subtype filtering.','','## What changed','','- **Urgency only:** the existing DELIVER head gains11 current-cargo risk features. Reconstruct minutes from type-normalized deadline/expiry values before minima; empty groups have zero minima and presence flags. Due/overdue ≤15min counts use half the shortest original30min window. Valid and expired physical cargo counts/weights remain explicit; other destinations’ urgent cargo is summarized. PICK, critic and other readout dimensions stay unchanged.','- **Coordination only:** PICK gains the same107-dimensional destination group already used by DELIVER. The visible pending summary includes the candidate itself and describes the current state; no counterfactual increments or hidden orders. DELIVER and other readouts retain the reference structure.','- No combined urgency+coordination model, reward/type weighting, wider candidate set, attention search or budget extension was performed.','','## Equivalent inference and CPU cost','','The reference already scores all six facilities in one batched call. The optional adapter reuses global context projections in PICK and DELIVER; near ties fall back to the canonical policy. Underlying parameter tensors are unchanged, and these adapters never enter PPO or the scientific final evaluator. Both factored and existing argmax-only modes were compared on complete Dev trajectories; all logits/value tolerances, actions and complete-day fields are retained in verification outputs.','','| Method | Parameters | Canonical B1 p50/p95 (µs) | Argmax-only B1 | Factored+guard B1 |','|---|---:|---:|---:|---:|']
    for m in methods:
        r=bench['aggregate'][m];cells=[]
        for mode in ['canonical','argmax_only','factored_guarded']:
            d=r['variants'][mode]['1'];cells.append(f'{d["p50_us_per_batch"]:.1f}/{d["p95_us_per_batch"]:.1f}')
        out.append(f'| {m} | {r["parameters"]:,} | '+' | '.join(cells)+' |')
    out+=['','| New method | Run wall-time range (s) | Sum of five run wall-times (s) |','|---|---:|---:|']
    for m in ['urgency','coordinated']:
        values=[r['wall_seconds'] for r in audit['runs'] if r['name'].startswith(m)]
        out.append(f'| {m} | {min(values):.1f}–{max(values):.1f} | {sum(values):.1f} |')
    out+=['','Five single-thread learners ran concurrently; some read-only development/inference checks overlapped training. These are observed run wall-times, not an isolated training-speed ratio. The suite manifest records actual elapsed time.']
    out+=['','Single CPU thread, identical archived real observation/mask inputs, inference_mode, three variant-order-rotated rounds,200 warmups+2,000 timed calls per model/variant/batch. Table medians summarize per-model round-median quantiles, not pooled p95s. Batch8 and all raw round quantiles are in `gen3_inference.json`. Inference was measured after all project training/evaluation jobs stopped. Floating-point logits need not be bitwise identical; observed full-day behavior is checked, not assumed.','','## Integrity and artifacts','',f'- Ten full scratch runs,10,240,000 transitions,10,000 PPO updates and110 Dev checkpoints, source `{audit["formal_source_commits"][0]}`.',f'- New Test-v3: {test["episodes"]:,} full episodes and {test["decisions"]:,} decisions; no illegal action or nonfinite required metric.','- [Training audit](gen3_training_audit.json), [development detail](gen3_development.md), [Test-v3 detail](gen3_test_v3.md), [learning curves](gen3_learning_curves.png), [tail curves](gen3_tail_curves.png), [paired Test-v3 differences](gen3_test_v3_paired.png).','- Protocols: `configs/gen3_holdout_freeze.json`, `configs/gen3_protocol.json`, `configs/gen3_test_v3_protocol.json`. Raw checkpoints, full-day and per-order failure records stay in the new `outputs/gen3_*` directories; these are ignored by Git and retained locally.','- No seed is chosen using Test-v3. Test-v3 is now consumed. No architecture/hyperparameter changes followed these results. Neither theoretical optimality nor new-map generalization is established.']
    Path('results/gen3_summary.md').write_text('\n'.join(out)+'\n');write_json(Path('results/gen3_summary.json'),{'generation':3,'primary':primary,'retention':retention,'inference':bench['aggregate'],'test_v3_status':'consumed','prior_generations_preserved':True})


if __name__=='__main__':main()
